/**
 * The workspace settings dropdown, ported from the app's WorkspaceSettings and
 * its snapshot section (src/panels/WorkspaceSettings.tsx), opened the way
 * WorkspaceTabs opens it (src/grid/WorkspaceTabs.tsx): a click on the active
 * tab portals it just under that tab. It shows the fieldnotes workspace of
 * the scenes, its three sessions and two snapshots; the controls respond as
 * in the app (Layout, show / hide, unfolding Snapshots, the restore preview
 * and its checkboxes) but nothing is saved, copied or started.
 */
import { useEffect, useRef, useState, type CSSProperties } from "react";
import { ChevronRight, ClipboardPaste, Copy, Eye, EyeOff, Folder, RotateCcw, Save, Trash2 } from "lucide-react";
import { ClaudeSessionIcon, MacDeviceIcon, type Rect } from "./parts";
import { THIS_MAC, DEVBOX } from "../../home/Chrome";
import { WIN_SIZE } from "../../home/Scenes";

/* ------------------------------------------------------------- the data -- */

const WORKSPACE = { name: "fieldnotes", color: "#7aa2f7" };
const SESSIONS = ["api", "web", "docs"];

// AUTO_COLUMNS (src/grid/autoLayout.ts) and the app's COLUMN_CHOICES.
const AUTO_COLUMNS = 0;
const COLUMN_CHOICES = [
  { value: AUTO_COLUMNS, label: "Auto" },
  { value: 2, label: "2" },
  { value: 3, label: "3" },
  { value: 4, label: "4" },
] as const;

type PreviewStatus = "start" | "running" | "resume" | "no-device";

interface SnapshotSession {
  session: string;
  host: string;
  agent: string;
  branch: string;
  /** What restoring finds (snapshotPreview in src/state/workspaceSnapshots.ts): "resume" needs Continue agent conversations. */
  status: PreviewStatus;
}

interface Snapshot {
  id: string;
  name: string;
  auto?: boolean;
  /** createdAt as SnapshotRow formats it (en-US): the day for a saved one, day and time for the auto-saved one. */
  when: string;
  sessions: SnapshotSession[];
}

// A snapshot saved by hand before a reboot (api is still running, web is
// gone, docs is back at its shell; jobs ran on the Devbox, now turned off),
// and the workspace's auto-saved one.
const SNAPSHOTS: Snapshot[] = [
  {
    id: "saved",
    name: "fieldnotes · 04:40 PM",
    when: "Nov 26",
    sessions: [
      { session: "api", host: "", agent: "Claude Code", branch: "main", status: "running" },
      { session: "web", host: "", agent: "Claude Code", branch: "main", status: "start" },
      { session: "docs", host: "", agent: "Claude Code", branch: "main", status: "resume" },
      { session: "jobs", host: DEVBOX.name.toLowerCase(), agent: "Codex", branch: "main", status: "no-device" },
    ],
  },
  {
    id: "auto",
    name: "Auto-saved",
    auto: true,
    when: "Nov 27, 09:12 AM",
    sessions: SESSIONS.map((session) => ({ session, host: "", agent: "Claude Code", branch: "main", status: "running" as const })),
  },
];

const PREVIEW_LABELS: Record<PreviewStatus, string> = { start: "Will start", resume: "Agent restarts", running: "Running", "no-device": "Device missing" };

/* ----------------------------------------------------- restore preview -- */

/** The app's SnapshotPreview: what restoring will do, session by session. */
function SnapshotPreview({ snapshot, onCancel }: { snapshot: Snapshot; onCancel: () => void }) {
  const [continueChats, setContinueChats] = useState(true);
  const [unchecked, setUnchecked] = useState<Set<string>>(() => new Set());
  // Without continuing conversations an open session at its shell is left as it is.
  const entries = snapshot.sessions.map((entry) => ({
    ...entry,
    key: `${entry.host}::${entry.session}`,
    status: entry.status === "resume" && !continueChats ? ("running" as const) : entry.status,
  }));
  const chosen = entries.filter((entry) => (entry.status === "start" || entry.status === "resume") && !unchecked.has(entry.key));
  const toggle = (key: string) =>
    setUnchecked((current) => {
      const next = new Set(current);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  return (
    <div className="snap-preview" role="group" aria-label="Restore preview">
      {entries.map((entry) => {
        const can = entry.status === "start" || entry.status === "resume";
        return (
          <label key={entry.key} className={`snap-preview-row ${can ? "" : "is-off"}`}>
            <input type="checkbox" checked={can && !unchecked.has(entry.key)} disabled={!can} onChange={() => toggle(entry.key)} aria-label={`Restore ${entry.session}`} />
            <span className="snap-preview-name">{entry.session}</span>
            <span className={`snap-preview-status is-${entry.status}`}>{PREVIEW_LABELS[entry.status]}</span>
            <span className="snap-preview-meta">{[entry.agent, `⎇ ${entry.branch}`].join(" · ")}</span>
          </label>
        );
      })}
      <label className="snap-preview-option">
        <input type="checkbox" checked={continueChats} onChange={() => setContinueChats(!continueChats)} />
        Continue agent conversations
      </label>
      <div className="snap-preview-actions">
        <button type="button" className="btn btn-sm" onClick={onCancel}>
          Cancel
        </button>
        {/* The app's AsyncButton, at rest. */}
        <button type="button" className="btn btn-sm btn-accent async-button" disabled={chosen.length === 0} aria-busy={false}>
          <span className="async-button-icon" style={{ width: 13, height: 13 }} aria-hidden="true">
            <RotateCcw size={13} strokeWidth={2} />
          </span>
          {chosen.length ? `Restore ${chosen.length}` : "Nothing to restore"}
        </button>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------ snapshots -- */

/** The app's SnapshotRow: its name (click to rename), what it holds, and its actions. */
function SnapshotRow({ snapshot, open, onToggle }: { snapshot: Snapshot; open: boolean; onToggle: () => void }) {
  const count = snapshot.sessions.length;
  return (
    <div className="snap-row">
      <div className="snap-row-copy">
        <button type="button" className="snap-name" title="Rename">
          {snapshot.name}
        </button>
        <span className="snap-meta" title={snapshot.sessions.map((entry) => entry.session).join(", ")}>
          {snapshot.auto ? "Auto · " : ""}
          {count} session{count === 1 ? "" : "s"} · {snapshot.when}
        </span>
      </div>
      <button type="button" className={`snap-icon ${open ? "is-on" : ""}`} title="Restore" aria-label={`Restore ${snapshot.name}`} aria-expanded={open} onClick={onToggle}>
        <RotateCcw size={14} />
      </button>
      <button type="button" className="snap-icon" title="Copy to share" aria-label={`Copy ${snapshot.name}`}>
        <Copy size={14} />
      </button>
      <button type="button" className="snap-icon" title="Delete" aria-label={`Delete ${snapshot.name}`}>
        <Trash2 size={14} />
      </button>
    </div>
  );
}

/** The app's SnapshotSection, folded away until needed. */
function SnapshotSection({ expanded: initialExpanded, previewing: initialPreview }: { expanded: boolean; previewing: string | null }) {
  const [expanded, setExpanded] = useState(initialExpanded);
  const [previewing, setPreviewing] = useState(initialPreview);
  return (
    <div className="field snap-section">
      <button type="button" className="snap-head" aria-expanded={expanded} onClick={() => setExpanded(!expanded)}>
        <ChevronRight size={13} className="snap-chevron" aria-hidden="true" />
        Snapshots
        <span className="field-hint">{SNAPSHOTS.length}</span>
      </button>
      {expanded ? (
        <div className="snap-body">
          <div className="snap-actions">
            <button type="button" className="btn btn-sm" title="Save this workspace's sessions and layout">
              <Save size={13} strokeWidth={2} />
              Save current
            </button>
            <button type="button" className="btn btn-sm" title="Add a snapshot copied in PzzaCode">
              <ClipboardPaste size={13} />
              Paste snapshot
            </button>
          </div>
          <div className="snap-list">
            {SNAPSHOTS.map((snapshot) => (
              <div key={snapshot.id} className="snap-item">
                <SnapshotRow snapshot={snapshot} open={previewing === snapshot.id} onToggle={() => setPreviewing(previewing === snapshot.id ? null : snapshot.id)} />
                {previewing === snapshot.id ? <SnapshotPreview snapshot={snapshot} onCancel={() => setPreviewing(null)} /> : null}
              </div>
            ))}
          </div>
        </div>
      ) : null}
    </div>
  );
}

/* ----------------------------------------------------------- the panel -- */

/**
 * WorkspaceTabs' dropStyle for a panel under `tab` (the active tab's box in
 * the window), clamped to the window like the app clamps it to its viewport.
 */
function dropStyle(tab: Rect, width = 288): CSSProperties {
  const bottom = tab.top + tab.height;
  return {
    position: "fixed",
    left: Math.max(8, Math.min(tab.left, WIN_SIZE.width - width - 8)),
    top: bottom + 5,
    width: Math.min(width, WIN_SIZE.width - 16),
    maxHeight: Math.max(80, WIN_SIZE.height - bottom - 16),
    zIndex: 300,
  };
}

/**
 * The fieldnotes workspace's settings, open under its tab. fieldnotes is the
 * default workspace (renamed), which the app never offers to delete.
 */
export function WorkspaceMenu({
  tab,
  snapshots = false,
  previewing = null,
  onHeight,
}: {
  /** The active tab's box in the window. */
  tab: Rect;
  /** Snapshots unfolded. */
  snapshots?: boolean;
  /** The snapshot whose restore preview is open. */
  previewing?: string | null;
  /** Told the panel's height (unscaled px) whenever it changes. */
  onHeight?: (height: number) => void;
}) {
  const root = useRef<HTMLDivElement>(null);
  const onHeightRef = useRef(onHeight);
  useEffect(() => {
    onHeightRef.current = onHeight;
  });
  // offsetHeight is the panel's own layout height, unaffected by the card's scale.
  useEffect(() => {
    const panel = root.current;
    if (!panel) return;
    const observer = new ResizeObserver(() => onHeightRef.current?.(panel.offsetHeight));
    observer.observe(panel);
    return () => observer.disconnect();
  }, []);
  const [columns, setColumns] = useState<number>(AUTO_COLUMNS);
  const [hidden, setHidden] = useState<Set<string>>(() => new Set());
  const toggleHidden = (session: string) =>
    setHidden((current) => {
      const next = new Set(current);
      if (next.has(session)) next.delete(session);
      else next.add(session);
      return next;
    });
  return (
    <div ref={root} className="menu menu-panel pzza-portal" style={dropStyle(tab)}>
      <div className="menu-body">
        <div className="ws-chip">
          <button className="ws-chip-avatar" style={{ color: WORKSPACE.color }} title="Icon & color">
            <Folder size={16} />
          </button>
          <span className="ws-name" title="Click to rename">
            {WORKSPACE.name}
          </span>
        </div>

        <div className="field">
          <span className="field-label">Layout</span>
          <div className="usage-seg ws-columns" role="group" aria-label="Grid columns">
            {COLUMN_CHOICES.map(({ value, label }) => (
              <button key={value} type="button" className={columns === value ? "on" : ""} aria-pressed={columns === value} onClick={() => setColumns(value)}>
                {label}
              </button>
            ))}
          </div>
        </div>

        <div className="field">
          <span className="field-label">
            Sessions
            <span className="field-hint">{SESSIONS.length}</span>
          </span>
          <div className="ws-sess-list">
            {SESSIONS.map((session) => {
              const isHidden = hidden.has(session);
              return (
                <div key={session} className={`ws-sess-row ${isHidden ? "hidden" : ""}`}>
                  <span className="ws-sess-icon">
                    <ClaudeSessionIcon />
                  </span>
                  <span className="ws-sess-name">{session}</span>
                  <span className="ws-sess-device" title="Running on">
                    <MacDeviceIcon size={11} />
                    {THIS_MAC.name}
                  </span>
                  <button className="ws-sess-toggle" title={isHidden ? "Show" : "Hide"} onClick={() => toggleHidden(session)}>
                    {isHidden ? <EyeOff size={14} /> : <Eye size={14} />}
                  </button>
                </div>
              );
            })}
          </div>
        </div>

        <SnapshotSection expanded={snapshots} previewing={previewing} />
      </div>
    </div>
  );
}
